import{_ as i,o as a,c as t,a2 as s}from"./chunks/framework.DnrXFDHb.js";const k=JSON.parse('{"title":"Domain 层总览","description":"StreamMUSE Domain 层的职责、子模块构成与核心约定","frontmatter":{"title":"Domain 层总览","description":"StreamMUSE Domain 层的职责、子模块构成与核心约定"},"headers":[],"relativePath":"architecture/domain/overview.md","filePath":"architecture/domain/overview.md","lastUpdated":1773326634000}'),o={name:"architecture/domain/overview.md"};function d(c,e,n,l,h,r){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="domain-层总览" tabindex="-1">Domain 层总览 <a class="header-anchor" href="#domain-层总览" aria-label="Permalink to &quot;Domain 层总览&quot;">​</a></h1><p>Domain 层是 StreamMUSE 的核心，定义了业务对象、领域接口和约束规则。该层<strong>不依赖任何外部框架</strong>，只使用 Python 标准库。</p><hr><h2 id="职责" tabindex="-1">职责 <a class="header-anchor" href="#职责" aria-label="Permalink to &quot;职责&quot;">​</a></h2><ul><li>定义系统的核心数据结构（<code>MusicalEvent</code>、<code>Tempo</code> 等）</li><li>声明外部接口的契约（<code>InputSource</code>、<code>OutputSink</code>、<code>InferenceEngine</code> Protocol）</li><li>封装业务规则（如 <code>MusicalEvent</code> 的不变性约束、tick 的语义）</li><li>提供日志领域对象（<code>LogEvent</code>、<code>InferenceEvent</code>、<code>SessionManager</code>）</li></ul><hr><h2 id="子模块一览" tabindex="-1">子模块一览 <a class="header-anchor" href="#子模块一览" aria-label="Permalink to &quot;子模块一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>子模块</th><th>路径</th><th>职责</th></tr></thead><tbody><tr><td><code>musical</code></td><td><code>domain/musical/</code></td><td>音乐数据类型：<code>MusicalEvent</code>、<code>EventType</code>、<code>Note</code>、转换函数、序列</td></tr><tr><td><code>timing</code></td><td><code>domain/timing/</code></td><td>时间模型：<code>Tempo</code>、<code>MusicalTime</code>、<code>PlaybackScheduler</code></td></tr><tr><td><code>logging</code></td><td><code>domain/logging/</code></td><td>会话日志领域对象：<code>LogEvent</code>、<code>InferenceEvent</code>、<code>SessionManager</code>、<code>MetricsCalculator</code></td></tr><tr><td><code>interfaces</code></td><td><code>domain/interfaces/</code></td><td>Protocol 定义：<code>InputSource</code>、<code>OutputSink</code>、<code>InferenceEngine</code>、<code>TimingInfo</code></td></tr></tbody></table><hr><h2 id="子模块依赖关系" tabindex="-1">子模块依赖关系 <a class="header-anchor" href="#子模块依赖关系" aria-label="Permalink to &quot;子模块依赖关系&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    interfaces --&gt; musical</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    musical --&gt; timing</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    logging --&gt; musical</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    logging --&gt; interfaces</span></span></code></pre></div><ul><li><code>interfaces</code> 依赖 <code>musical</code>（Protocol 方法签名中使用 <code>MusicalEvent</code>）</li><li><code>musical</code> 依赖 <code>timing</code>（<code>MusicalSequence</code> 持有 <code>Tempo</code>）</li><li><code>logging</code> 依赖 <code>musical</code>（<code>LogEvent</code> 包含 pitch 等音乐字段）</li></ul><hr><h2 id="核心不变性约定" tabindex="-1">核心不变性约定 <a class="header-anchor" href="#核心不变性约定" aria-label="Permalink to &quot;核心不变性约定&quot;">​</a></h2><h3 id="musicalevent-不变性" tabindex="-1"><code>MusicalEvent</code> 不变性 <a class="header-anchor" href="#musicalevent-不变性" aria-label="Permalink to &quot;\`MusicalEvent\` 不变性&quot;">​</a></h3><p><code>MusicalEvent</code> 是 <code>frozen=True</code> 的 dataclass，创建后不可修改：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">event </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MusicalEvent(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">tick</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">pitch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">event_type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EventType.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NOTE_ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">event.tick </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 报错：FrozenInstanceError</span></span></code></pre></div><p><strong>Placeholder 事件</strong>：<code>is_placeholder=True</code> 的事件必须将 <code>pitch</code> 设为 <code>-1</code>，用于填充空缺的时间位置，不代表真实音符。</p><h3 id="tick-语义" tabindex="-1">Tick 语义 <a class="header-anchor" href="#tick-语义" aria-label="Permalink to &quot;Tick 语义&quot;">​</a></h3><ul><li>1 tick = 1/<code>ticks_per_beat</code> 拍（默认 <code>ticks_per_beat=4</code>，即 1 tick = 1/4 拍）</li><li>Tick 是系统内部时间单位，单调递增，从 0 开始</li><li><code>Tempo.seconds_per_tick</code> 给出实时时长</li></ul><hr><h2 id="各子模块详细文档" tabindex="-1">各子模块详细文档 <a class="header-anchor" href="#各子模块详细文档" aria-label="Permalink to &quot;各子模块详细文档&quot;">​</a></h2><ul><li><a href="./musical.html">musical — 音乐数据类型</a></li><li><a href="./timing.html">timing — 时间与调度</a></li><li><a href="./logging.html">logging — 会话日志</a></li><li><a href="./interfaces.html">interfaces — Domain 接口 Protocol</a></li></ul>`,23)])])}const g=i(o,[["render",d]]);export{k as __pageData,g as default};
